def write_ascii(path, text):
    # 以 ASCII 字节写入，\\uXXXX 是 JSON 源码转义而非真实 UTF-8 代理
    # 字节（CESU-8/UTF-16 中转均不合法），故文件仍是合法 UTF-8。
    with open(path, "wb") as handle:
        handle.write(text.encode("ascii"))
    return path


def surrogate_lock(directory, packages, root_deps=None, extra_top=None, name="lock.json"):
    """packages: {名称: 版本}；root_deps 默认取全部包名。返回文件路径。"""
    if root_deps is None:
        root_deps = {name: "1.0.0" for name in packages}
    entries = {"": {"dependencies": dict(root_deps)}}
    for pkg_name, version in packages.items():
        entries["node_modules/" + pkg_name] = {"version": version}
    data = {"lockfileVersion": 3, "packages": entries}
    if extra_top:
        data.update(extra_top)
    path = os.path.join(directory, name)
    with open(path, "w", encoding="utf-8") as handle:
        json.dump(data, handle, ensure_ascii=False)
    return path

